// app.js — History Lab orchestrator: connect, run the turn state machine, gate state
// behind the human-review verdict, persist to storage, and post the final storybook to chat.
//
//   start -> Scene + 3 options -> choose -> Historian's Ruling
//         -> HUMAN GATE (Approve = advance + accuracy; Flag = re-decide)
//         -> ... -> Storybook (chat.append_artifact)
//
// The app is fully playable offline (Mock mode default ON). When connected to a real Nexus
// and Mock is off, the scene + ruling are generated by anna.agent.session / llm.complete.
// The assistant can also open this window straight onto a scenario via open_app_view
// (payload { scenarioId }); see boot().

import { connect, isConnected, setTitle, appendArtifact, getEntryPayload } from "./sdk.js";
import { loadRun, saveRun } from "./store.js";
import { generateScene, generateRuling } from "./agent.js";
import { generateArt } from "./image.js";
import { getScenario, listScenarios } from "./scenarios.js";
import { tallyVerdict, buildStorybookPayload } from "./logic.js";
import * as ui from "./ui.js";

const view = document.getElementById("view");
const mockToggle = document.getElementById("mockToggle");

let MOCK = true;
const sessionRef = { sess: null, uuid: null };
let scenario = null;
let run = null;
let runEtag = null;

const DEFAULT_SCENARIO = "cuban-missile-1962";
const runKey = (sid, rid) => `run:${sid}:${rid}`;

function newRun(scenarioId) {
  return {
    scenarioId, runId: "default",
    started: false, finished: false,
    turn: 0,
    totalVerdicts: 0, correctVerdicts: 0, accuracyScore: 100,
    branchPath: [], flaggedRulings: [],
    appSessionUuid: null,
  };
}

async function persist() {
  runEtag = await saveRun(runKey(run.scenarioId, run.runId), run, runEtag);
}

function updateHud() {
  ui.setHud(`Turn ${Math.min(run.turn + 1, scenario.turns.length)} · Accuracy ${run.accuracyScore}%`, run.accuracyScore);
}

// ---- boot ----
async function boot() {
  mockToggle.addEventListener("change", () => { MOCK = mockToggle.checked; });
  try {
    await connect();
    MOCK = mockToggle.checked;
    ui.setStatus(isConnected() ? "connected to Anna" : "offline (mock)");
  } catch (e) {
    mockToggle.checked = true; MOCK = true;
    ui.setStatus("offline — running scripted mock");
    console.warn("[app] connect failed; mock mode", e);
  }

  scenario = getScenario(DEFAULT_SCENARIO);

  // If the assistant opened this window with a scenario payload (open_app_view), honor it:
  // jump straight into that scenario instead of showing the picker.
  const entry = getEntryPayload();
  const requestedId = entry && (entry.scenarioId || entry.scenario);
  if (requestedId && getScenario(requestedId)) {
    scenario = getScenario(requestedId);
    run = newRun(requestedId);
    run.started = true;
    await persist();
    await setTitle(`History Lab — ${scenario.name}`);
    route();
    return;
  }

  const loaded = await loadRun(runKey(DEFAULT_SCENARIO, "default"));
  if (loaded && loaded.value) {
    run = loaded.value; runEtag = loaded.etag; sessionRef.uuid = run.appSessionUuid;
    scenario = getScenario(run.scenarioId) || scenario;
  } else {
    run = newRun(DEFAULT_SCENARIO);
  }

  await setTitle("History Lab");
  route();
}

function route() {
  updateHud();
  if (!run.started) return showPicker();
  if (run.finished) return showStorybook();
  return showTurn();
}

function showPicker() {
  ui.renderScenePicker(view, listScenarios(), async (sid) => {
    scenario = getScenario(sid);
    run = newRun(sid);
    run.started = true;
    runEtag = null;
    sessionRef.sess = null; sessionRef.uuid = null;
    await persist();
    route();
  });
}

async function showTurn() {
  const turnIndex = run.turn;
  ui.renderThinking(view, "The historian is setting the scene…");

  const sceneData = await generateScene(scenario, turnIndex, sessionRef, { mock: MOCK });
  if (sessionRef.uuid && run.appSessionUuid !== sessionRef.uuid) {
    run.appSessionUuid = sessionRef.uuid; persist();
  }
  const imageUrl = await generateArt(sceneData.image_prompt, { mock: MOCK });

  ui.renderTurn(view, {
    turnNumber: turnIndex + 1,
    totalTurns: scenario.turns.length,
    scene: sceneData.scene,
    options: sceneData.options,
    imageUrl,
    live: sceneData.live,
  }, (optIndex) => onChoose(turnIndex, optIndex, sceneData, imageUrl));

  await setTitle(`Turn ${turnIndex + 1} · Accuracy ${run.accuracyScore}%`);
}

async function onChoose(turnIndex, optIndex, sceneData, imageUrl) {
  const choiceLabel = sceneData.options[optIndex];
  ui.renderThinking(view, "The historian is writing a ruling…");

  const ruling = await generateRuling(scenario, turnIndex, optIndex, sessionRef, { mock: MOCK });

  ui.renderRuling(view, {
    turnNumber: turnIndex + 1,
    choiceLabel,
    ruling: ruling.ruling,
    live: ruling.live,
  }, (verdict) => onVerdict(turnIndex, choiceLabel, ruling, imageUrl, verdict));
}

async function onVerdict(turnIndex, choiceLabel, ruling, imageUrl, verdict) {
  const correct = tallyVerdict(run, verdict, ruling);

  if (verdict === "flag") {
    run.flaggedRulings.push({ turn: turnIndex + 1, choice: choiceLabel, ruling: ruling.ruling, wasAccurate: ruling.accurate });
  }

  const isLastTurn = turnIndex >= scenario.turns.length - 1;
  await setTitle(`Turn ${turnIndex + 1} · Accuracy ${run.accuracyScore}%`);
  updateHud();
  await persist();

  ui.renderVerdictResult(view, {
    correct,
    verdict,
    accurate: ruling.accurate,
    whatReallyHappened: ruling.whatReallyHappened,
    advances: verdict === "approve",
    isLastTurn,
  }, async (action) => {
    if (action === "advance") {
      run.branchPath.push({
        turn: turnIndex + 1, choice: choiceLabel, ruling: ruling.ruling,
        verdict, accurate: ruling.accurate, correct,
        whatReallyHappened: ruling.whatReallyHappened, imageUrl,
      });
      run.turn = turnIndex + 1;
      if (run.turn >= scenario.turns.length) {
        run.finished = true;
        await finish();
      }
      await persist();
      route();
    } else {
      // Flag -> re-decide the same turn with the truth now known.
      await persist();
      showTurn();
    }
  });
}

async function finish() {
  const summary = `History Lab · ${scenario.name} — fact-check accuracy ${run.accuracyScore}% (${run.correctVerdicts}/${run.totalVerdicts})`;
  await appendArtifact({
    kind: "history-lab-storybook",
    summary,
    data: buildStorybookPayload(scenario, run),
  });
}

function showStorybook() {
  ui.renderStorybook(view, { scenarioName: scenario.name, run }, async () => {
    sessionRef.sess = null; sessionRef.uuid = null;
    run = newRun(scenario.id);
    runEtag = null;
    await persist();
    route();
  });
}

boot();
